
BEGIN;
CREATE TABLE IF NOT EXISTS staging.bis_cbpol_policy_rate_phase2_observation (observation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pipeline_run_id uuid NOT NULL REFERENCES meta.pipeline_run(pipeline_run_id), source_id uuid NOT NULL REFERENCES meta.source(source_id), dataset_release_id uuid REFERENCES meta.dataset_release(dataset_release_id), indicator_code text NOT NULL, indicator_name text NOT NULL, territory_code text NOT NULL, territory_label text NOT NULL, provider_period_code text NOT NULL, period_year integer NOT NULL, period_month integer NOT NULL, value numeric, unit_code text NOT NULL, unit_label text NOT NULL, observation_status text NOT NULL, decimal_precision integer, attribute_hash text NOT NULL, attributes jsonb NOT NULL, source_payload jsonb NOT NULL, CONSTRAINT uq_staging_bis_cbpol_policy_rate_phase2 UNIQUE (pipeline_run_id, indicator_code, territory_code, provider_period_code, unit_code, attribute_hash));
CREATE TEMP TABLE _task213_bis_rows (indicator_code text, indicator_name text, territory_code text, territory_label text, provider_period_code text, period_year integer, period_month integer, value numeric, unit_code text, unit_label text, observation_status text, decimal_precision integer, attribute_hash text, attributes jsonb, source_payload jsonb) ON COMMIT DROP;
WITH upsert_source AS (INSERT INTO meta.source (source_code, source_name, source_home_url, license_note) VALUES ('BIS_PUBLIC_SDMX_API', 'Bank for International Settlements public SDMX API', 'https://www.bis.org/', 'BIS public SDMX API; campaign scope stored in dataset release and pipeline run metadata') ON CONFLICT (source_code) DO UPDATE SET source_name=EXCLUDED.source_name, source_home_url=EXCLUDED.source_home_url RETURNING source_id), source_row AS (SELECT source_id FROM upsert_source UNION ALL SELECT source_id FROM meta.source WHERE source_code='BIS_PUBLIC_SDMX_API' LIMIT 1), upsert_release AS (INSERT INTO meta.dataset_release (source_id, provider_dataset_code, release_key, release_date, source_url, raw_artifact_path, raw_sha256, metadata) SELECT source_id,'BIS:WS_CBPOL','bis-ws-cbpol-snapshot-prepared-20260712t114554z',NULL::date,'https://stats.bis.org/api/v2/data/dataflow/BIS/WS_CBPOL/1.0/M.AU+BR+CA+CH+CL+CN+CO+CZ+DK+GB+HU+HK+ID+IL+IN+IS+JP+KR+KW+MA+MK+MX+MY+NO+NZ+PE+PH+PL+RO+RS+RU+SA+SE+TH+TR+US+ZA?startPeriod=2015-01&endPeriod=2026-06','data/raw/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-2015m01-2026m06-raw.xml','fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6','{"candidate_cell_count": 5106, "explicit_missing_value_count": 24, "observed_value_count": 5082, "provider_metadata": {"acquired_at_utc": "2026-07-12T11:45:53+00:00", "content_type": null, "dataflow": {"agency_id": "BIS", "id": "WS_CBPOL", "version": "1.0"}, "dataset_action": "Information", "dataset_attributes": {"UNIT_MEASURE": "368", "UNIT_MULT": "0"}, "dimension_at_observation": "TIME_PERIOD", "http_status": 200, "message_id": "IDREF09770ee1-0359-403b-ac1c-c28ad81bc42a", "prepared": "2026-07-12T11:45:54Z", "sender": "UNKNOWN", "structure_id": "BIS_WS_CBPOL_1_0", "structure_namespace": "urn:sdmx:org.sdmx.infomodel.datastructure.Dataflow=BIS:WS_CBPOL(1.0):ObsLevelDim:TIME_PERIOD"}, "task": "TASK-213"}'::jsonb FROM source_row ON CONFLICT (source_id, provider_dataset_code, release_key) DO UPDATE SET release_date=EXCLUDED.release_date, source_url=EXCLUDED.source_url, raw_artifact_path=EXCLUDED.raw_artifact_path, raw_sha256=EXCLUDED.raw_sha256, metadata=EXCLUDED.metadata RETURNING dataset_release_id), release_row AS (SELECT dataset_release_id FROM upsert_release UNION ALL SELECT dr.dataset_release_id FROM meta.dataset_release dr JOIN source_row s ON dr.source_id=s.source_id WHERE dr.provider_dataset_code='BIS:WS_CBPOL' AND dr.release_key='bis-ws-cbpol-snapshot-prepared-20260712t114554z' LIMIT 1), upsert_run AS (INSERT INTO meta.pipeline_run (run_key, source_id, dataset_release_id, pipeline_name, finished_at, status, input_parameters, artifact_manifest) SELECT 'task-213-bis-cbpol-policy-rate-phase2',s.source_id,r.dataset_release_id,'bis_cbpol_policy_rate_phase2_campaign',now(),'succeeded','{"endPeriod": "2026-06", "frequency": "M", "reference_areas": ["AU", "BR", "CA", "CH", "CL", "CN", "CO", "CZ", "DK", "GB", "HU", "HK", "ID", "IL", "IN", "IS", "JP", "KR", "KW", "MA", "MK", "MX", "MY", "NO", "NZ", "PE", "PH", "PL", "RO", "RS", "RU", "SA", "SE", "TH", "TR", "US", "ZA"], "startPeriod": "2015-01"}'::jsonb,'{"manifest": "data/processed/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-manifest.json", "normalized": "data/processed/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-normalized.json", "raw": "data/raw/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-2015m01-2026m06-raw.xml"}'::jsonb FROM source_row s CROSS JOIN release_row r ON CONFLICT (run_key) DO UPDATE SET source_id=EXCLUDED.source_id, dataset_release_id=EXCLUDED.dataset_release_id, finished_at=EXCLUDED.finished_at, status=EXCLUDED.status, input_parameters=EXCLUDED.input_parameters, artifact_manifest=EXCLUDED.artifact_manifest RETURNING pipeline_run_id) SELECT 1;
WITH run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') DELETE FROM staging.bis_cbpol_policy_rate_phase2_observation s USING run_row WHERE s.pipeline_run_id=run_row.pipeline_run_id;
WITH run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') DELETE FROM curated.fact_observation f USING run_row WHERE f.pipeline_run_id=run_row.pipeline_run_id;
WITH run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') DELETE FROM meta.lineage_event le USING run_row WHERE le.pipeline_run_id=run_row.pipeline_run_id;
WITH run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') DELETE FROM meta.quality_check qc USING run_row WHERE qc.pipeline_run_id=run_row.pipeline_run_id;
WITH source_row AS (SELECT source_id FROM meta.source WHERE source_code='BIS_PUBLIC_SDMX_API'), release_row AS (SELECT dataset_release_id FROM meta.dataset_release WHERE provider_dataset_code='BIS:WS_CBPOL' AND release_key='bis-ws-cbpol-snapshot-prepared-20260712t114554z'), run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') INSERT INTO staging.bis_cbpol_policy_rate_phase2_observation (pipeline_run_id,source_id,dataset_release_id,indicator_code,indicator_name,territory_code,territory_label,provider_period_code,period_year,period_month,value,unit_code,unit_label,observation_status,decimal_precision,attribute_hash,attributes,source_payload) SELECT run.pipeline_run_id,s.source_id,rel.dataset_release_id,r.* FROM _task213_bis_rows r CROSS JOIN source_row s CROSS JOIN release_row rel CROSS JOIN run_row run;
WITH source_row AS (SELECT source_id FROM meta.source WHERE source_code='BIS_PUBLIC_SDMX_API') INSERT INTO curated.dim_indicator (source_id, source_indicator_code, indicator_name, topic) SELECT DISTINCT s.source_id,r.indicator_code,r.indicator_name,'central_bank_policy_rate' FROM source_row s CROSS JOIN _task213_bis_rows r ON CONFLICT (source_id, source_indicator_code) DO UPDATE SET indicator_name=EXCLUDED.indicator_name, topic=EXCLUDED.topic;
WITH source_row AS (SELECT source_id FROM meta.source WHERE source_code='BIS_PUBLIC_SDMX_API'), release_row AS (SELECT dataset_release_id FROM meta.dataset_release WHERE provider_dataset_code='BIS:WS_CBPOL' AND release_key='bis-ws-cbpol-snapshot-prepared-20260712t114554z'), run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2'), staged AS (SELECT st.* FROM staging.bis_cbpol_policy_rate_phase2_observation st JOIN run_row r ON st.pipeline_run_id=r.pipeline_run_id) INSERT INTO curated.fact_observation (source_id,dataset_release_id,pipeline_run_id,indicator_id,territory_id,period_id,unit_id,attribute_set_id,value,as_of_date,observation_status) SELECT s.source_id,rel.dataset_release_id,run.pipeline_run_id,ind.indicator_id,terr.territory_id,per.period_id,unit.unit_id,aset.attribute_set_id,staged.value,'2026-07-12'::date,staged.observation_status FROM staged CROSS JOIN source_row s CROSS JOIN release_row rel CROSS JOIN run_row run JOIN curated.dim_indicator ind ON ind.source_id=s.source_id AND ind.source_indicator_code=staged.indicator_code JOIN curated.dim_territory terr ON terr.canonical_territory_code=staged.territory_code JOIN curated.dim_period per ON per.frequency='M' AND per.period_start_date=make_date(staged.period_year,staged.period_month,1) JOIN curated.dim_unit unit ON unit.unit_code=staged.unit_code JOIN curated.dim_attribute_set aset ON aset.attribute_hash=staged.attribute_hash;
WITH source_row AS (SELECT source_id FROM meta.source WHERE source_code='BIS_PUBLIC_SDMX_API'), run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') INSERT INTO meta.lineage_event (pipeline_run_id,source_id,event_type,from_artifact,to_artifact,checksum_sha256,row_count,details) SELECT run.pipeline_run_id,s.source_id,event_type,from_artifact,to_artifact,checksum,row_count,details FROM source_row s CROSS JOIN run_row run CROSS JOIN (VALUES ('raw_bis_sdmx_acquired','data/raw/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-2015m01-2026m06-raw.xml','data/processed/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-normalized.json','fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6',5106::bigint,'{"provider_dataset_code": "BIS:WS_CBPOL", "task": "TASK-213"}'::jsonb),('normalized_rows_loaded','data/processed/task213_bis_cbpol_policy_rate_phase2_campaign/active/task-213-bis-cbpol-policy-rate-normalized.json','curated.fact_observation','185026ae4bbbed58ad2a30f6b2b1b09860514997883b97705af1abf1e87e4b78',5106::bigint,'{"provider_dataset_code": "BIS:WS_CBPOL", "task": "TASK-213"}'::jsonb)) AS events(event_type,from_artifact,to_artifact,checksum,row_count,details);
WITH run_row AS (SELECT pipeline_run_id FROM meta.pipeline_run WHERE run_key='task-213-bis-cbpol-policy-rate-phase2') INSERT INTO meta.quality_check (pipeline_run_id,check_name,check_status,severity,observed_value,expected_value,details) SELECT run.pipeline_run_id,check_name,check_status,'error',observed_value,expected_value,details FROM run_row run CROSS JOIN (VALUES ('candidate_cell_count', CASE WHEN (SELECT count(*) FROM _task213_bis_rows)=5106 THEN 'pass' ELSE 'fail' END,(SELECT count(*)::numeric FROM _task213_bis_rows),5106::numeric,'{"task": "TASK-213"}'::jsonb),('observed_missing_reconciliation', CASE WHEN ((SELECT count(*) FROM _task213_bis_rows WHERE observation_status='observed')=5082 AND (SELECT count(*) FROM _task213_bis_rows WHERE observation_status='missing')=24) THEN 'pass' ELSE 'fail' END,(SELECT count(*)::numeric FROM _task213_bis_rows),5106::numeric,'{"task": "TASK-213"}'::jsonb),('acquisition_errors_absent','pass',0::numeric,0::numeric,'{"task": "TASK-213"}'::jsonb)) AS checks(check_name,check_status,observed_value,expected_value,details);
COMMIT;
