INSERT INTO _task213_bis_rows VALUES
('BIS:WS_CBPOL:CENTRAL_BANK_POLICY_RATE:PERCENT:M', 'Central bank policy rate', 'AUS', 'Australia', '2015-M01', 2015, 1, '2.5', 'PERCENT', 'Percent', 'observed', 1, '074da72f80fe0d25eed84351eea428fdbf19f21dcc98874f046d6f1fe675b1e8', '{"compilation": "From 2 Aug 1990 onwards: cash rate target; from 23 Jan 1990 to 1 Aug 1990: middle of the cash rate target range; from 7 Apr 1976 to 22 Jan 1990: interbank overnight cash rate.", "dataflow": "WS_CBPOL", "decimals": "4", "frequency": "M", "iso3_code": "AUS", "measure": "central_bank_policy_rate", "obs_conf": "F", "obs_status": "A", "provider_dataset_code": "BIS:WS_CBPOL", "ref_area": "AU", "series_key": "M.AU", "snapshot_prepared": "2026-07-12T11:45:54Z", "snapshot_raw_sha256": "fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6", "snapshot_release_key": "bis-ws-cbpol-snapshot-prepared-20260712t114554z", "source_provider": "BIS", "source_ref": "Reserve Bank of Australia", "task": "TASK-213", "title": "Central bank policy rates - Australia - Monthly - End of period", "unit_measure_provider_code": "368", "unit_mult": "0"}'::jsonb, '{"missing_basis": null, "obs_attributes": {"OBS_CONF": "F", "OBS_STATUS": "A", "OBS_VALUE": "2.5", "TIME_PERIOD": "2015-01"}, "series_attributes": {"COMPILATION": "From 2 Aug 1990 onwards: cash rate target; from 23 Jan 1990 to 1 Aug 1990: middle of the cash rate target range; from 7 Apr 1976 to 22 Jan 1990: interbank overnight cash rate.", "DECIMALS": "4", "FREQ": "M", "REF_AREA": "AU", "SOURCE_REF": "Reserve Bank of Australia", "SUPP_INFO_BREAKS": "This rate can be considered the official policy rate as from 23 Jan 1990. Australia had a managed exchange rate regime prior to 1983, in an environment of capital controls. The RBA did not have an explicit target interest rate prior to 23 Jan 1990. The BIS publishes a representative rate for that period. Between  23 Jan 1990 and 31 Jul the middle of the cash rate target corridor is used.", "TITLE": " Central bank policy rates - Australia - Monthly - End of period"}}'::jsonb),
('BIS:WS_CBPOL:CENTRAL_BANK_POLICY_RATE:PERCENT:M', 'Central bank policy rate', 'BRA', 'Brazil', '2015-M01', 2015, 1, '12.25', 'PERCENT', 'Percent', 'observed', 2, '09642fe25fcb32733ce8a5f5940113c771fe4199d1742b5454d1eaf3d9706362', '{"compilation": "From 5 Mar 1999 onwards Central Bank target, money market (SELIC) overnight rate; from 1 Jul 1996 to 4 Mar 1999: Central Bank official rediscount rate; from 4 Jun 1986 to 30 Jun 1996: official market intervention rate, representative rate.", "dataflow": "WS_CBPOL", "decimals": "4", "frequency": "M", "iso3_code": "BRA", "measure": "central_bank_policy_rate", "obs_conf": "F", "obs_status": "A", "provider_dataset_code": "BIS:WS_CBPOL", "ref_area": "BR", "series_key": "M.BR", "snapshot_prepared": "2026-07-12T11:45:54Z", "snapshot_raw_sha256": "fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6", "snapshot_release_key": "bis-ws-cbpol-snapshot-prepared-20260712t114554z", "source_provider": "BIS", "source_ref": "Central Bank of Brazil", "task": "TASK-213", "title": "Central bank policy rates - Brazil - Monthly - End of period", "unit_measure_provider_code": "368", "unit_mult": "0"}'::jsonb, '{"missing_basis": null, "obs_attributes": {"OBS_CONF": "F", "OBS_STATUS": "A", "OBS_VALUE": "12.25", "TIME_PERIOD": "2015-01"}, "series_attributes": {"COMPILATION": "From 5 Mar 1999 onwards Central Bank target, money market (SELIC) overnight rate; from 1 Jul 1996 to 4 Mar 1999: Central Bank official rediscount rate; from 4 Jun 1986 to 30 Jun 1996: official market intervention rate, representative rate.", "DECIMALS": "4", "FREQ": "M", "REF_AREA": "BR", "SOURCE_REF": "Central Bank of Brazil", "SUPP_INFO_BREAKS": "This rate can be considered the official policy rate as from 5 Mar 1999. From Jul 1996 to 4 Mar 1999, the TBC rate (basic interest rate) was used; from Mar 1999 onwards, the TARGET for the SELIC rate was used, which defines a threshold for the open market operations. The SELIC rate is a daily interest rate for overnight interbank loans collateralised by government bonds (overnight federal funds) registered and traded at the SELIC (Sistema Especial de Liquida\u00e7\u00e3o e Cust\u00f3dia - Special System for Settlement and Custody).", "TITLE": " Central bank policy rates - Brazil - Monthly - End of period"}}'::jsonb),
('BIS:WS_CBPOL:CENTRAL_BANK_POLICY_RATE:PERCENT:M', 'Central bank policy rate', 'CAN', 'Canada', '2015-M01', 2015, 1, '0.75', 'PERCENT', 'Percent', 'observed', 2, 'd79dd7e46b2598e67c7b5768982c581371d793462e1da9b7b34d341cf579e7f5', '{"compilation": "From 1 Jun 1994 onwards: Central Bank target, overnight rate; from 27 Jul 1960 to 31 May 1994: official bank rate.", "dataflow": "WS_CBPOL", "decimals": "4", "frequency": "M", "iso3_code": "CAN", "measure": "central_bank_policy_rate", "obs_conf": "F", "obs_status": "A", "provider_dataset_code": "BIS:WS_CBPOL", "ref_area": "CA", "series_key": "M.CA", "snapshot_prepared": "2026-07-12T11:45:54Z", "snapshot_raw_sha256": "fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6", "snapshot_release_key": "bis-ws-cbpol-snapshot-prepared-20260712t114554z", "source_provider": "BIS", "source_ref": "Bank of Canada", "task": "TASK-213", "title": "Central bank policy rates - Canada - Monthly - End of period", "unit_measure_provider_code": "368", "unit_mult": "0"}'::jsonb, '{"missing_basis": null, "obs_attributes": {"OBS_CONF": "F", "OBS_STATUS": "A", "OBS_VALUE": "0.75", "TIME_PERIOD": "2015-01"}, "series_attributes": {"COMPILATION": "From 1 Jun 1994 onwards: Central Bank target, overnight rate; from 27 Jul 1960 to 31 May 1994: official bank rate.", "DECIMALS": "4", "FREQ": "M", "REF_AREA": "CA", "SOURCE_REF": "Bank of Canada", "SUPP_INFO_BREAKS": "In Jun 1994 the Bank of Canada (BoC) began shifting emphasis from the bank rate to the target for the overnight rate as its key monetary policy instrument. In Feb 1999 the target for the overnight rate was defined as the midpoint of the band, or 25 basis points below the bank rate. In May 2001 the BoC began emphasizing the target as its key interest rate in its communications with the public.", "TITLE": " Central bank policy rates - Canada - Monthly - End of period"}}'::jsonb),
('BIS:WS_CBPOL:CENTRAL_BANK_POLICY_RATE:PERCENT:M', 'Central bank policy rate', 'CHE', 'Switzerland', '2015-M01', 2015, 1, '-0.75', 'PERCENT', 'Percent', 'observed', 2, '225af24af0d794976df513c5bbad4da532713c3a25115fb3e80c3490b252cd24', '{"compilation": "From 13 June 2019 onwards SNB Policy rate; From 1 Jan 2000 to 12 June 2019 mid-point of the SNB target range; from 1 Jan 1946 to 31 Dec 1999: discount rate.", "dataflow": "WS_CBPOL", "decimals": "4", "frequency": "M", "iso3_code": "CHE", "measure": "central_bank_policy_rate", "obs_conf": "F", "obs_status": "A", "provider_dataset_code": "BIS:WS_CBPOL", "ref_area": "CH", "series_key": "M.CH", "snapshot_prepared": "2026-07-12T11:45:54Z", "snapshot_raw_sha256": "fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6", "snapshot_release_key": "bis-ws-cbpol-snapshot-prepared-20260712t114554z", "source_provider": "BIS", "source_ref": "Swiss National Bank", "task": "TASK-213", "title": "Central bank policy rates - Switzerland - Monthly - End of period", "unit_measure_provider_code": "368", "unit_mult": "0"}'::jsonb, '{"missing_basis": null, "obs_attributes": {"OBS_CONF": "F", "OBS_STATUS": "A", "OBS_VALUE": "-0.75", "TIME_PERIOD": "2015-01"}, "series_attributes": {"COMPILATION": "From 13 June 2019 onwards SNB Policy rate; From 1 Jan 2000 to 12 June 2019 mid-point of the SNB target range; from 1 Jan 1946 to 31 Dec 1999: discount rate.", "DECIMALS": "4", "FREQ": "M", "REF_AREA": "CH", "SOURCE_REF": "Swiss National Bank", "TITLE": " Central bank policy rates - Switzerland - Monthly - End of period"}}'::jsonb),
('BIS:WS_CBPOL:CENTRAL_BANK_POLICY_RATE:PERCENT:M', 'Central bank policy rate', 'CHL', 'Chile', '2015-M01', 2015, 1, '3', 'PERCENT', 'Percent', 'observed', NULL, 'daa894bc174ebd9a9a5b70cf2e3d0691446bec5425ffcb1b351deda6fc6087ac', '{"compilation": "From 1997 onwards: official monetary policy rate.", "dataflow": "WS_CBPOL", "decimals": "4", "frequency": "M", "iso3_code": "CHL", "measure": "central_bank_policy_rate", "obs_conf": "F", "obs_status": "A", "provider_dataset_code": "BIS:WS_CBPOL", "ref_area": "CL", "series_key": "M.CL", "snapshot_prepared": "2026-07-12T11:45:54Z", "snapshot_raw_sha256": "fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6", "snapshot_release_key": "bis-ws-cbpol-snapshot-prepared-20260712t114554z", "source_provider": "BIS", "source_ref": "Central Bank of Chile", "task": "TASK-213", "title": "Central bank policy rates - Chile - Monthly - End of period", "unit_measure_provider_code": "368", "unit_mult": "0"}'::jsonb, '{"missing_basis": null, "obs_attributes": {"OBS_CONF": "F", "OBS_STATUS": "A", "OBS_VALUE": "3", "TIME_PERIOD": "2015-01"}, "series_attributes": {"COMPILATION": "From 1997 onwards: official monetary policy rate.", "DECIMALS": "4", "FREQ": "M", "REF_AREA": "CL", "SOURCE_REF": "Central Bank of Chile", "SUPP_INFO_BREAKS": "Monetary policy was nominalized as from 9 Aug 2001, and the monetary policy interest rate was initially set at an annual 6.5%. Before that date, the monetary policy rate was defined in terms of a commonly used unit of account, indexed to one-month-lagged CPI.", "TITLE": " Central bank policy rates - Chile - Monthly - End of period"}}'::jsonb),
('BIS:WS_CBPOL:CENTRAL_BANK_POLICY_RATE:PERCENT:M', 'Central bank policy rate', 'CHN', 'China', '2015-M01', 2015, 1, '5.6', 'PERCENT', 'Percent', 'observed', 1, '3529ad3e735dc16d298c7c2366a13195c1a93be265903f3d42eea16b1a6314d0', '{"compilation": "From 20 Aug 2019 onwards: Loan Prime Rate  (1 year): from 1 Jan 1996 till 19 Aug 2019: Official lending rate (1 year).", "dataflow": "WS_CBPOL", "decimals": "4", "frequency": "M", "iso3_code": "CHN", "measure": "central_bank_policy_rate", "obs_conf": "F", "obs_status": "A", "provider_dataset_code": "BIS:WS_CBPOL", "ref_area": "CN", "series_key": "M.CN", "snapshot_prepared": "2026-07-12T11:45:54Z", "snapshot_raw_sha256": "fc99baf519a2a1ff206f517183a6b77c080e367f99ac15f80ec1010e8125b2f6", "snapshot_release_key": "bis-ws-cbpol-snapshot-prepared-20260712t114554z", "source_provider": "BIS", "source_ref": "People''s Bank of China", "task": "TASK-213", "title": "Central bank policy rates - China - Monthly - End of period", "unit_measure_provider_code": "368", "unit_mult": "0"}'::jsonb, '{"missing_basis": null, "obs_attributes": {"OBS_CONF": "F", "OBS_STATUS": "A", "OBS_VALUE": "5.6", "TIME_PERIOD": "2015-01"}, "series_attributes": {"COMPILATION": "From 20 Aug 2019 onwards: Loan Prime Rate  (1 year): from 1 Jan 1996 till 19 Aug 2019: Official lending rate (1 year).", "DECIMALS": "4", "FREQ": "M", "REF_AREA": "CN", "SOURCE_REF": "People''s Bank of China", "TITLE": " Central bank policy rates - China - Monthly - End of period"}}'::jsonb),
